import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * How the customer list is narrowed down.
 *
 * <p>Both parts are optional and combine with AND: a customer is matched when
 * every name term occurs in its first or last name <em>and</em> its status is
 * one of the selected ones. An empty {@code name} matches every name, an empty
 * {@code statuses} matches every status, and {@link #EMPTY} matches everything.
 *
 * <p>Name matching ignores case and accents, so {@code makinen}, {@code MAKINEN}
 * and {@code mäkinen} all match {@code Mäkinen}. {@link #normalize(String)} is
 * what makes that work, and the backend applies it to both sides.
 *
 * @param name     the raw text the user typed; whitespace separates the terms
 * @param statuses the statuses to show, empty for all of them
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    /** The filter that matches every customer. */
    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = (name == null) ? "" : name;
        statuses = (statuses == null || statuses.isEmpty())
                ? Set.of()
                // An EnumSet iterates in declaration order, which is the order
                // the statuses appear in the URL.
                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
    }

    /**
     * The name filter as the terms a customer has to match, normalized for
     * comparison. Empty when no name was entered.
     */
    public List<String> terms() {
        String normalized = normalize(name);
        return normalized.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalized));
    }

    /** {@code true} when this filter matches every customer. */
    public boolean isEmpty() {
        return statuses.isEmpty() && terms().isEmpty();
    }

    /**
     * Folds a name to the form names are compared in: lower case, without
     * accents and without surrounding whitespace.
     */
    public static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return COMBINING_MARKS.matcher(decomposed).replaceAll("")
                .toLowerCase(Locale.ROOT)
                .trim();
    }
}
