/**
 * Lists customers in a lazily loaded {@link Grid}, narrowed by a name and a
 * status filter.
 *
 * <p>The grid never holds the whole data set: it asks the backend for one page
 * at a time and asks separately for the number of matching rows. Filtering does
 * not change that — the filter is passed down to the backend, so a filtered grid
 * still holds one page and still learns its size from a count query.
 *
 * <p>The filter lives in the URL as the query parameters {@code name} and
 * {@code status}, for example {@code /?name=vir&status=ACTIVE,CLOSED}, so a
 * narrowed list survives a reload and can be sent to a colleague.
 */
@Route("")
@PageTitle("Customers")
public class CustomerListView extends VerticalLayout implements BeforeEnterObserver {

    private static final String NAME_PARAMETER = "name";
    private static final String STATUS_PARAMETER = "status";
    private static final String STATUS_SEPARATOR = ",";

    /**
     * How long typing has to pause before the filter is sent to the server.
     * Long enough that a name costs one query rather than one per keystroke,
     * short enough that the grid still feels like it follows the typing.
     */
    private static final int TYPING_PAUSE_MS = 300;

    private final CustomerService customerService;

    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
    private final TextField nameFilter = new TextField();
    private final MultiSelectComboBox<CustomerStatus> statusFilter = new MultiSelectComboBox<>("Status");
    private final Span summary = new Span();

    private GridLazyDataView<Customer> dataView;

    /** The total row count, which no filter changes. */
    private final int totalCount;

    private CustomerFilter filter = CustomerFilter.EMPTY;

    /** The number of rows matching {@link #filter}, as counted by the backend. */
    private int matchingCount;

    /** Set while the filter fields are being populated from the URL. */
    private boolean readingFilterFromUrl;

    public CustomerListView(CustomerService customerService) {
